css:
.fc { display: flex; flex-wrap: wrap; gap: 8px; }
.fc__b { cursor: pointer; padding: 10px 18px; border: 1px solid var(--line); border-radius: var(--radius-input); background: var(--card); font: 700 16px/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; color: var(--accent); transition: background var(--hcm-dur) var(--hcm-ease), color var(--hcm-dur) var(--hcm-ease); }
.fc__b:hover { border-color: var(--accent); }
.fc__b[data-bz-active], .fc__b[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #fff; }
